     9→import Foundation
    10→
    11→struct SessionDirectories: Hashable, Codable {
    12→    let dataDirectory: URL
    13→    let cacheDirectory: URL
    14→    
    15→    var dataPath: String {
    16→        dataDirectory.path(percentEncoded: false)
    17→    }
    18→
    19→    var cachePath: String {
    20→        cacheDirectory.path(percentEncoded: false)
    21→    }
    22→    
    23→    // MARK: Data Management
    24→    
    25→    /// Removes the directories from disk if they have been created.
    26→    func delete() {
    27→        do {
    28→            if FileManager.default.directoryExists(at: dataDirectory) {
    29→                try FileManager.default.removeItem(at: dataDirectory)
    30→            }
    31→        } catch {
    32→            MXLog.failure("Failed deleting the session data: \(error)")
    33→        }
    34→        do {
    35→            if FileManager.default.directoryExists(at: cacheDirectory) {
    36→                try FileManager.default.removeItem(at: cacheDirectory)
    37→            }
    38→        } catch {
    39→            MXLog.failure("Failed deleting the session caches: \(error)")
    40→        }
    41→    }
    42→    
    43→    /// Deletes the Rust state store and event cache data, leaving the crypto store and both
    44→    /// session directories in place along with any other data that may have been written in them.
    45→    func deleteTransientUserData() {
    46→        do {
    47→            let prefix = "matrix-sdk-state"
    48→            try deleteFiles(at: dataDirectory, with: prefix)
    49→        } catch {
    50→            MXLog.failure("Failed clearing state store: \(error)")
    51→        }
    52→        do {
    53→            let prefix = "matrix-sdk-event-cache"
    54→            try deleteFiles(at: cacheDirectory, with: prefix)
    55→        } catch {
    56→            MXLog.failure("Failed clearing event cache store: \(error)")
    57→        }
    58→    }
    59→    
    60→    /// Check that mission critical files (the crypto db) are still in the right place when restoring a session
    61→    /// iOS might decide to move the app with its user defaults and keychain but without
    62→    /// some of the files stored in the shared container e.g. after a device transfer, offloading etc.
    63→    /// If that happens we should fail the session restoration.
    64→    func isNonTransientUserDataValid() -> Bool {
    65→        FileManager.default.fileExists(atPath: dataPath.appending("/matrix-sdk-crypto.sqlite3"))
    66→    }
    67→    
    68→    private func deleteFiles(at url: URL, with prefix: String) throws {
    69→        let sessionDirectoryContents = try FileManager.default.contentsOfDirectory(at: url, includingPropertiesForKeys: nil)
    70→        for url in sessionDirectoryContents where url.lastPathComponent.hasPrefix(prefix) {
    71→            try FileManager.default.removeItem(at: url)
    72→        }
    73→    }
    74→}
    75→
    76→extension SessionDirectories {
    77→    /// Creates a fresh set of session directories for a new user.
    78→    init() {
    79→        let sessionDirectoryName = UUID().uuidString
    80→        dataDirectory = .sessionsBaseDirectory.appending(component: sessionDirectoryName)
    81→        cacheDirectory = .sessionCachesBaseDirectory.appending(component: sessionDirectoryName)
    82→    }
    83→    
    84→    /// Creates the session directories for a user who has a single session directory stored without a separate caches directory.
    85→    init(dataDirectory: URL) {
    86→        self.dataDirectory = dataDirectory
    87→        cacheDirectory = .sessionCachesBaseDirectory.appending(component: dataDirectory.lastPathComponent)
    88→    }
    89→}
    90→
    91→extension SessionDirectories: CustomStringConvertible {
    92→    var description: String {
    93→        "Data: \(dataPath) Caches: \(cachePath)"
    94→    }
    95→}
    96→

