     9→import Foundation
    10→
    11→// MARK: - Custom URLs
    12→
    13→extension URL {
    14→    /// The URL of the primary app group container.
    15→    static var appGroupContainerDirectory: URL {
    16→        guard let url = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: InfoPlistReader.main.appGroupIdentifier) else {
    17→            MXLog.error("Application Group unavailable, falling back to the application folder")
    18→            // Browserstack doesn't properly handle AppGroup entitlements so this fails, presumably because of the resigning happening on their side
    19→            // Try using the normal app folder instead of the app group
    20→            // https://www.browserstack.com/docs/app-automate/appium/troubleshooting/entitlements-error
    21→            
    22→            return URL.applicationSupportDirectory.deletingLastPathComponent().deletingLastPathComponent()
    23→        }
    24→        
    25→        return url
    26→    }
    27→    
    28→    static var appGroupLogsDirectory: URL {
    29→        appGroupContainerDirectory
    30→            .appending(component: "Library", directoryHint: .isDirectory)
    31→            .appending(component: "Logs", directoryHint: .isDirectory)
    32→            .appending(component: InfoPlistReader.main.baseBundleIdentifier, directoryHint: .isDirectory)
    33→    }
    34→
    35→    /// The base directory where all session data is stored.
    36→    static var sessionsBaseDirectory: URL {
    37→        let applicationSupportSessionsURL = applicationSupportBaseDirectory.appending(component: "Sessions", directoryHint: .isDirectory)
    38→        
    39→        try? FileManager.default.createDirectoryIfNeeded(at: applicationSupportSessionsURL)
    40→
    41→        return applicationSupportSessionsURL
    42→    }
    43→    
    44→    /// The base directory where all application support data is stored.
    45→    static var applicationSupportBaseDirectory: URL {
    46→        var url = appGroupContainerDirectory
    47→            .appending(component: "Library", directoryHint: .isDirectory)
    48→            .appending(component: "Application Support", directoryHint: .isDirectory)
    49→            .appending(component: InfoPlistReader.main.baseBundleIdentifier, directoryHint: .isDirectory)
    50→
    51→        try? FileManager.default.createDirectoryIfNeeded(at: url)
    52→        
    53→        do {
    54→            var resourceValues = URLResourceValues()
    55→            resourceValues.isExcludedFromBackup = true
    56→            try url.setResourceValues(resourceValues)
    57→        } catch {
    58→            MXLog.error("Failed excluding Application Support from backups")
    59→        }
    60→
    61→        return url
    62→    }
    63→    
    64→    /// The base directory where all application support data is stored.
    65→    static var sessionCachesBaseDirectory: URL {
    66→        let url = appGroupContainerDirectory
    67→            .appending(component: "Library", directoryHint: .isDirectory)
    68→            .appending(component: "Caches", directoryHint: .isDirectory)
    69→            .appending(component: InfoPlistReader.main.baseBundleIdentifier, directoryHint: .isDirectory)
    70→            .appending(component: "Sessions", directoryHint: .isDirectory)
    71→
    72→        try? FileManager.default.createDirectoryIfNeeded(at: url)
    73→        
    74→        // Caches are excluded from backups automatically.
    75→        // https://developer.apple.com/library/archive/documentation/FileManagement/Conceptual/FileSystemProgrammingGuide/FileSystemOverview/FileSystemOverview.html
    76→
    77→        return url
    78→    }
    79→    
    80→    /// The app group temporary directory (useful for transferring files between different bundles).
    81→    ///
    82→    /// **Note:** This `tmp` directory doesn't appear to behave as expected as it isn't being tidied up by the system.
    83→    /// Make sure to manually tidy up any files you place in here once you've transferred them from one bundle to another.
    84→    static var appGroupTemporaryDirectory: URL {
    85→        let url = appGroupContainerDirectory
    86→            .appending(component: "tmp", directoryHint: .isDirectory)
    87→
    88→        try? FileManager.default.createDirectoryIfNeeded(at: url)
    89→        
    90→        // Temporary files are excluded from backups automatically.
    91→        // https://developer.apple.com/library/archive/documentation/FileManagement/Conceptual/FileSystemProgrammingGuide/FileSystemOverview/FileSystemOverview.html
    92→
    93→        return url
    94→    }
    95→    
    96→    var globalProxy: String? {
    97→        let span = MXLog.createSpan("Global proxy")
    98→        span.enter()
    99→        defer {
   100→            span.exit()
   101→        }
   102→        
   103→        guard let proxySettings = CFNetworkCopySystemProxySettings()?.takeRetainedValue() else {
   104→            MXLog.error("Failed retrieving proxy settings")
   105→            return nil
   106→        }
   107→        
   108→        let proxies = CFNetworkCopyProxiesForURL(self as CFURL, proxySettings).takeRetainedValue() as? [[CFString: Any]]
   109→        
   110→        guard let firstProxy = proxies?.first,
   111→              let proxyType = firstProxy[kCFProxyTypeKey] as? String,
   112→              proxyType != kCFProxyTypeNone as String else {
   113→            MXLog.info("No global proxy configured.")
   114→            return nil
   115→        }
   116→        
   117→        MXLog.info("Found \(String(describing: proxies?.count)) proxies, using the first one.")
   118→        MXLog.info("Proxy type is \(proxyType)")
   119→            
   120→        guard let host = firstProxy[kCFProxyHostNameKey] as? String else {
   121→            MXLog.error("Found proxy with invalid host name")
   122→            return nil
   123→        }
   124→        
   125→        let port = firstProxy[kCFProxyPortNumberKey] as? Int
   126→        
   127→        MXLog.info("Found proxy host: \(host), port: \(String(describing: port))")
   128→        
   129→        if let port {
   130→            return "\(host):\(port)"
   131→        } else {
   132→            return host
   133→        }
   134→    }
   135→    
   136→    // MARK: Mocks
   137→    
   138→    static var mockMXCAudio: URL {
   139→        "mxc://matrix.org/1234567890AuDiO"
   140→    }
   141→
   142→    static var mockMXCFile: URL {
   143→        "mxc://matrix.org/1234567890FiLe"
   144→    }
   145→
   146→    static var mockMXCImage: URL {
   147→        "mxc://matrix.org/1234567890ImAgE"
   148→    }
   149→
   150→    static var mockMXCVideo: URL {
   151→        "mxc://matrix.org/1234567890ViDeO"
   152→    }
   153→
   154→    static var mockMXCAvatar: URL {
   155→        "mxc://matrix.org/1234567890AvAtAr"
   156→    }
   157→
   158→    static var mockMXCUserAvatar: URL {
   159→        "mxc://matrix.org/1234567890AvAtArUsEr"
   160→    }
   161→}
   162→
   163→// MARK: - Helpers
   164→
   165→extension URL: @retroactive ExpressibleByStringLiteral {
   166→    public init(stringLiteral value: StaticString) {
   167→        guard let url = URL(string: "\(value)") else {
   168→            fatalError("The static string used to create this URL is invalid")
   169→        }
   170→        
   171→        self = url
   172→    }
   173→    
   174→    /// Sanitises the URL for use as the name of a directory.
   175→    func asDirectoryName() -> String {
   176→        absoluteString.asURLDirectoryName()
   177→    }
   178→}
   179→
   180→extension String {
   181→    /// Assumes that the string is a URL and sanitises it for use as the name of a directory.
   182→    func asURLDirectoryName() -> String {
   183→        replacingOccurrences(of: "https://", with: "")
   184→            .trimmingCharacters(in: CharacterSet(charactersIn: "/"))
   185→            .replacing(/[:\/\p{C}]/, with: "-")
   186→    }
   187→}
   188→
   189→// MARK: - Phishing Confirmation URL
   190→
   191→extension URL {
   192→    static let confirmationScheme = "confirm"
   193→    
   194→    var requiresConfirmation: Bool {
   195→        scheme == Self.confirmationScheme
   196→    }
   197→    
   198→    var confirmationParameters: ConfirmURLParameters? {
   199→        guard requiresConfirmation,
   200→              let queryItems = URLComponents(url: self, resolvingAgainstBaseURL: true)?.queryItems else {
   201→            return nil
   202→        }
   203→        return ConfirmURLParameters(queryItems: queryItems)
   204→    }
   205→}
   206→
   207→struct ConfirmURLParameters {
   208→    static let internalURLKey = "internalURL"
   209→    static let displayStringKey = "displayString"
   210→    
   211→    let internalURL: URL
   212→    let displayString: String
   213→    
   214→    var urlQueryItems: [URLQueryItem] {
   215→        [URLQueryItem(name: Self.internalURLKey, value: internalURL.absoluteString),
   216→         URLQueryItem(name: Self.displayStringKey, value: displayString)]
   217→    }
   218→}
   219→
   220→extension ConfirmURLParameters {
   221→    init?(queryItems: [URLQueryItem]) {
   222→        guard let internalURLString = queryItems.first(where: { $0.name == Self.internalURLKey })?.value,
   223→              let internalURL = URL(string: internalURLString),
   224→              let externalURLString = queryItems.first(where: { $0.name == Self.displayStringKey })?.value else {
   225→            return nil
   226→        }
   227→        displayString = externalURLString
   228→        self.internalURL = internalURL
   229→    }
   230→}
