     9→import Foundation
    10→@preconcurrency import KeychainAccess
    11→import MatrixRustSDK
    12→
    13→enum KeychainControllerService: String {
    14→    case sessions
    15→    case tests
    16→
    17→    var restorationTokenID: String {
    18→        InfoPlistReader.main.baseBundleIdentifier + "." + rawValue
    19→    }
    20→    
    21→    var mainID: String {
    22→        InfoPlistReader.main.baseBundleIdentifier + ".keychain.\(rawValue)"
    23→    }
    24→}
    25→
    26→final class KeychainController: KeychainControllerProtocol {
    27→    /// The keychain responsible for storing account restoration tokens (keyed by userID).
    28→    private let restorationTokenKeychain: Keychain
    29→    /// The keychain responsible for storing all other secrets in the app (keyed by `Key`s).
    30→    private let mainKeychain: Keychain
    31→    
    32→    private enum Key: String {
    33→        case appLockPINCode
    34→        case appLockBiometricState
    35→    }
    36→
    37→    init(service: KeychainControllerService, accessGroup: String) {
    38→        restorationTokenKeychain = Keychain(service: service.restorationTokenID, accessGroup: accessGroup)
    39→        mainKeychain = Keychain(service: service.mainID, accessGroup: accessGroup)
    40→    }
    41→    
    42→    // MARK: - Restoration Tokens
    43→
    44→    func setRestorationToken(_ restorationToken: RestorationToken, forUsername username: String) {
    45→        do {
    46→            let tokenData = try JSONEncoder().encode(restorationToken)
    47→            try restorationTokenKeychain.set(tokenData, key: username)
    48→        } catch {
    49→            MXLog.error("Failed storing user restore token with error: \(error)")
    50→        }
    51→    }
    52→
    53→    func restorationTokenForUsername(_ username: String) -> RestorationToken? {
    54→        do {
    55→            guard let tokenData = try restorationTokenKeychain.getData(username) else {
    56→                return nil
    57→            }
    58→            
    59→            return try JSONDecoder().decode(RestorationToken.self, from: tokenData)
    60→        } catch RestorationTokenError.slidingSyncProxyNotSupported {
    61→            MXLog.error("Unsupported user restore token (contains sliding sync proxy). Deleting token.")
    62→            removeRestorationTokenForUsername(username)
    63→            return nil
    64→        } catch {
    65→            MXLog.error("Failed retrieving user restore token")
    66→            return nil
    67→        }
    68→    }
    69→
    70→    func restorationTokens() -> [KeychainCredentials] {
    71→        restorationTokenKeychain.allKeys().compactMap { username in
    72→            guard let restorationToken = restorationTokenForUsername(username) else {
    73→                return nil
    74→            }
    75→
    76→            return KeychainCredentials(userID: username, restorationToken: restorationToken)
    77→        }
    78→    }
    79→
    80→    func removeRestorationTokenForUsername(_ username: String) {
    81→        MXLog.warning("Removing restoration token for user: \(username).")
    82→        
    83→        do {
    84→            try restorationTokenKeychain.remove(username)
    85→        } catch {
    86→            MXLog.error("Failed removing restore token with error: \(error)")
    87→        }
    88→    }
    89→
    90→    func removeAllRestorationTokens() {
    91→        MXLog.warning("Removing all user restoration tokens.")
    92→        
    93→        do {
    94→            try restorationTokenKeychain.removeAll()
    95→        } catch {
    96→            MXLog.error("Failed removing all tokens")
    97→        }
    98→    }
    99→    
   100→    // MARK: - ClientSessionDelegate
   101→    
   102→    func retrieveSessionFromKeychain(userId: String) throws -> Session {
   103→        MXLog.info("Retrieving an updated Session from the keychain.")
   104→        guard let session = restorationTokenForUsername(userId)?.session else {
   105→            throw ClientError.Generic(msg: "Failed to find RestorationToken in the Keychain.", details: nil)
   106→        }
   107→        return session
   108→    }
   109→    
   110→    func saveSessionInKeychain(session: Session) {
   111→        MXLog.info("Saving session changes in the keychain.")
   112→        
   113→        guard let oldToken = restorationTokenForUsername(session.userId) else {
   114→            MXLog.error("Failed retrieving the restoration token for \(session.userId)")
   115→            fatalError("Something has gone mega wrong, all bets are off.")
   116→        }
   117→        let restorationToken = RestorationToken(session: session,
   118→                                                sessionDirectories: oldToken.sessionDirectories,
   119→                                                passphrase: oldToken.passphrase,
   120→                                                pusherNotificationClientIdentifier: oldToken.pusherNotificationClientIdentifier)
   121→        setRestorationToken(restorationToken, forUsername: session.userId)
   122→    }
   123→    
   124→    // MARK: - App Secrets
   125→    
   126→    func resetSecrets() {
   127→        MXLog.warning("Resetting main keychain.")
   128→        
   129→        do {
   130→            try mainKeychain.removeAll()
   131→        } catch {
   132→            MXLog.error("Failed resetting the main keychain.")
   133→        }
   134→    }
   135→    
   136→    func containsPINCode() throws -> Bool {
   137→        try mainKeychain.contains(Key.appLockPINCode.rawValue)
   138→    }
   139→    
   140→    func setPINCode(_ pinCode: String) throws {
   141→        try mainKeychain.set(pinCode, key: Key.appLockPINCode.rawValue)
   142→    }
   143→    
   144→    func pinCode() -> String? {
   145→        do {
   146→            return try mainKeychain.getString(Key.appLockPINCode.rawValue)
   147→        } catch {
   148→            MXLog.error("Failed retrieving the PIN code.")
   149→            return nil
   150→        }

